// Builds the SVG sprite of the reader site (templates/reader/icons.html) from the Lucide icons the
// staff app already depends on. The reader pages are server-rendered and load no icon font or CDN:
// each page inlines this sprite once and draws icons with <svg class="icon"><use href="#i-name"/></svg>.
//
//   npm run icons        (rerun after adding a name below; the generated file is committed)
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const iconDir = join(root, "node_modules", "lucide-vue-next", "dist", "esm", "icons");
const target = join(root, "..", "document_manager", "templates", "reader", "icons.html");

const NAMES = [
  "triangle-alert", "archive", "arrow-left", "arrow-right", "bell", "book-open-text", "building-2", "calendar",
  "check", "chevron-down", "chevron-left", "chevron-right", "circle-check", "circle-x", "clipboard-list", "clock",
  "copy", "download", "external-link", "eye", "file-text", "folder", "globe", "hash", "inbox", "info", "key-round",
  "layers", "loader", "lock", "log-in", "log-out", "mail", "map-pin", "menu", "message-square", "moon", "network",
  "phone", "plus", "printer", "search", "send", "shield-check", "sliders-horizontal", "sun", "trash-2", "user",
  "user-plus", "users", "x",
];

function nodesOf(name) {
  const source = readFileSync(join(iconDir, `${name}.js`), "utf8");
  const match = source.match(/createLucideIcon\("[^"]+",\s*(\[[\s\S]*?\n?\])\s*\);/);
  if (!match) throw new Error(`cannot read the icon ${name}`);
  return Function(`"use strict"; return (${match[1]});`)();
}

const attr = ([key, value]) => (key === "key" ? "" : ` ${key}="${String(value).replace(/"/g, "&quot;")}"`);
const symbol = (name) =>
  `<symbol id="i-${name}" viewBox="0 0 24 24">${nodesOf(name)
    .map(([tag, attrs]) => `<${tag}${Object.entries(attrs).map(attr).join("")}/>`)
    .join("")}</symbol>`;

const html = `{#- Generated by frontend/scripts/build-reader-icons.mjs (Lucide, ISC). Do not edit by hand. -#}
<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false">
${NAMES.map(symbol).join("\n")}
</svg>
`;
writeFileSync(target, html);
console.log(`${NAMES.length} icons -> ${target}`);
